package main

import "fmt"

type Animal struct {
	Name string
}

func (a Animal) Breathe() string {
	return a.Name + " is breathing"
}

func (a Animal) Eat(food string) string {
	return a.Name + " eats " + food
}

type Dog struct {
	Animal
	Breed string
}

func (d Dog) Bark() string {
	return d.Name + " says: Woof!"
}

type Cat struct {
	Animal
	Indoor bool
}

// Cat overrides Eat
func (c Cat) Eat(food string) string {
	return c.Name + " delicately eats " + food
}

type Eater interface {
	Eat(string) string
}

func feed(e Eater, food string) {
	fmt.Println(e.Eat(food))
}

func main() {
	dog := Dog{
		Animal: Animal{Name: "Rex"},
		Breed:  "Golden Retriever",
	}

	cat := Cat{
		Animal: Animal{Name: "Whiskers"},
		Indoor: true,
	}

	// Promoted methods
	fmt.Println(dog.Breathe())
	fmt.Println(dog.Bark())
	fmt.Println(dog.Name, "is a", dog.Breed)

	// Shadowed method
	fmt.Println(cat.Eat("fish"))
	fmt.Println(cat.Animal.Eat("fish")) // direct access

	// Interface polymorphism
	fmt.Println("--- Feeding time ---")
	feed(dog, "bone")
	feed(cat, "tuna")
}
